-- Farmakodynamikken som mekanismekort (docs/farmakodynamikk-kort-kartlegging.md)
do $farmakodynamikk$
declare
  administrator uuid;
  konvertering jsonb;
  side uuid;
  e record;
  kort jsonb;
  posisjon bigint;
  objekt uuid;
begin
  select p.id into administrator from public.profiles p where p.username = 'peohol' and p.role = 'admin';
  if administrator is null then
    raise notice 'Fant ingen administrator med brukernavnet %, så importen hoppes over.', 'peohol';
    return;
  end if;
  perform set_config('request.jwt.claims', jsonb_build_object('sub', administrator, 'role', 'authenticated')::text, true);

  for konvertering in select * from jsonb_array_elements('[{"stoff":"karvedilol","fra":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Selektiv alfa-1-adrenerg reseptorantagonist og ikke-selektiv beta-1-reseptorantagonist."}]},{"type":"paragraph","content":[{"type":"text","text":"Karvedilol er en vasodilaterende ikke-selektiv betablokker som reduserer den perifere vaskulære motstanden ved selektiv alfa 1-reseptor blokkade o'
    'g undertrykker renin-angiotensin systemet via ikke-selektiv betablokkade."}]},{"type":"paragraph","content":[{"type":"text","text":"Kombinasjonen av betablokkade og alfa-1-modulert vasodilatasjon gir redusert blodtrykk og reduserer ventrikulær pre- og afterload."}]}]},"kort":[{"maal":"α1-adrenerg reseptor","effekt":"Antagonist","mekanisme":"antagonisme","retning":"ned","kvalifikasjon":"Selektiv α1'
    '-blokkade","dokument":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Karvedilol er en vasodilaterende ikke-selektiv betablokker som reduserer den perifere vaskulære motstanden ved selektiv alfa 1-reseptor blokkade og undertrykker renin-angiotensin systemet via ikke-selektiv betablokkade."}]}]}},{"maal":"β1-adrenerg reseptor","effekt":"Antagonist / blokkerer","mekani'
    'sme":"antagonisme","retning":"ned","kvalifikasjon":"Ikke-selektiv betablokkade","dokument":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Kombinasjonen av betablokkade og alfa-1-modulert vasodilatasjon gir redusert blodtrykk og reduserer ventrikulær pre- og afterload."}]}]}},{"maal":"β2-adrenerg reseptor","effekt":"Antagonist / blokkerer","mekanisme":"antagonisme","'
    'retning":"ned","kvalifikasjon":"Ikke-selektiv betablokkade"}]},{"stoff":"klomipramin","fra":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Hemmer reopptak av serotonin, men også noradrenalin. Har også alfa1-adrenerge, antikolinerge og antihistaminerge effekter."}]},{"type":"paragraph","content":[{"type":"text","text":"Aktiv metabolitt: desmetylklomipramin."}]}]},"ko'
    'rt":[{"maal":"Serotoninreopptak / SERT","effekt":"Hemmer reopptak","mekanisme":"reopptakshemming","retning":"ned","dokument":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Aktiv metabolitt: desmetylklomipramin."}]}]}},{"maal":"Noradrenalinreopptak / NET","effekt":"Hemmer reopptak","mekanisme":"reopptakshemming","retning":"ned"},{"maal":"α1-adrenerg reseptor","effekt'
    '":"α1-adrenerg effekt","mekanisme":"reseptorpavirkning","retning":"ukjent"},{"maal":"Kolinerge reseptorer","effekt":"Antikolinerg effekt","mekanisme":"antagonisme","retning":"ned","merknad":"Kilden bruker effektnavn, ikke eksplisitt «antagonist»"},{"maal":"Histaminreseptorer","effekt":"Antihistaminerg effekt","mekanisme":"antagonisme","retning":"ned","merknad":"Kilden bruker effektnavn, ikke ekspl'
    'isitt «antagonist»"}]},{"stoff":"klorprotiksen","fra":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Høy affinitet (antagonist) til D"},{"type":"text","text":"1","marks":[{"type":"subscript"}]},{"type":"text","text":"-, D"},{"type":"text","text":"2","marks":[{"type":"subscript"}]},{"type":"text","text":"-, 5-HT"},{"type":"text","text":"2","marks":[{"type":"subscript'
    '"}]},{"type":"text","text":"- og α"},{"type":"text","text":"1","marks":[{"type":"subscript"}]},{"type":"text","text":"-adrenerge reseptorer samt kolinerge reseptorer. Også antihistamineffekt."}]},{"type":"paragraph","content":[{"type":"text","text":"Reseptorbindingsprofilen ligner den til klozapin, men klorprotiksen har 10 ganger høyere affinitet for dopaminreseptorer."}]}]},"kort":[{"maal":"D1-re'
    'septor","effekt":"Antagonist","mekanisme":"antagonisme","retning":"ned","kvalifikasjon":"Høy affinitet","dokument":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Reseptorbindingsprofilen ligner den til klozapin, men klorprotiksen har 10 ganger høyere affinitet for dopaminreseptorer."}]}]}},{"maal":"D2-reseptor","effekt":"Antagonist","mekanisme":"antagonisme","retnin'
    'g":"ned","kvalifikasjon":"Høy affinitet"},{"maal":"5-HT2-reseptor","effekt":"Antagonist","mekanisme":"antagonisme","retning":"ned","kvalifikasjon":"Høy affinitet"},{"maal":"α1-adrenerg reseptor","effekt":"Antagonist","mekanisme":"antagonisme","retning":"ned","kvalifikasjon":"Høy affinitet"},{"maal":"Kolinerge reseptorer","effekt":"Antagonist","mekanisme":"antagonisme","retning":"ned","kvalifikasjo'
    'n":"Høy affinitet"},{"maal":"Histaminreseptorer","effekt":"Antihistaminerg effekt","mekanisme":"reseptorpavirkning","retning":"ukjent","merknad":"Subtype ikke oppgitt"}]},{"stoff":"klozapin","fra":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Antagonist på serotonerge (5-HT"},{"type":"text","text":"2A","marks":[{"type":"subscript"}]},{"type":"text","text":"), alfa-'
    'adrenerge, kolinerge, histaminerge og dopaminerge reseptorer. Lav affinitet til D"},{"type":"text","text":"1","marks":[{"type":"subscript"}]},{"type":"text","text":"-, D"},{"type":"text","text":"2","marks":[{"type":"subscript"}]},{"type":"text","text":"-, D"},{"type":"text","text":"3","marks":[{"type":"subscript"}]},{"type":"text","text":"- og D"},{"type":"text","text":"5","marks":[{"type":"subscr'
    'ipt"}]},{"type":"text","text":"-reseptorer, men viser høy affinitet til D"},{"type":"text","text":"4","marks":[{"type":"subscript"}]},{"type":"text","text":"-reseptorer."}]}]},"kort":[{"maal":"5-HT2A-reseptor","effekt":"Antagonist","mekanisme":"antagonisme","retning":"ned"},{"maal":"α-adrenerge reseptorer","effekt":"Antagonist","mekanisme":"antagonisme","retning":"ned","merknad":"Subtype ikke oppg'
    'itt"},{"maal":"Kolinerge reseptorer","effekt":"Antagonist","mekanisme":"antagonisme","retning":"ned"},{"maal":"Histaminerge reseptorer","effekt":"Antagonist","mekanisme":"antagonisme","retning":"ned"},{"maal":"D1-reseptor","effekt":"Antagonist","mekanisme":"antagonisme","retning":"ned","kvalifikasjon":"Lav affinitet"},{"maal":"D2-reseptor","effekt":"Antagonist","mekanisme":"antagonisme","retning":'
    '"ned","kvalifikasjon":"Lav affinitet"},{"maal":"D3-reseptor","effekt":"Antagonist","mekanisme":"antagonisme","retning":"ned","kvalifikasjon":"Lav affinitet"},{"maal":"D4-reseptor","effekt":"Antagonist","mekanisme":"antagonisme","retning":"ned","kvalifikasjon":"Høy affinitet"},{"maal":"D5-reseptor","effekt":"Antagonist","mekanisme":"antagonisme","retning":"ned","kvalifikasjon":"Lav affinitet"}]},{"'
