    'oc","content":[{"type":"paragraph","content":[{"type":"text","text":"Kalsiumantagonist, fenylalkylaminderivat. Hemmer selektivt langsomme spenningstyrte L-type kalsiumkanaler i sarcolemma i både hjertemuskelceller og glatte muskelceller. Dette fører også til mindre frigivelse av kalsiumioner intracellulært. Effekten er vasodilatasjon (redusert afterload), nedsatt perifer motstand og reduksjon i bl'
    'odtrykk. Vasodilatasjon skjer også i kransarteriene."}]},{"type":"paragraph","content":[{"type":"text","text":"Redusert smerte ved angina pectoris fordi verapamil reduserer hjertets pumpekraft som betyr redusert oksygenbehov og samtidig øker blodforsyningen til hjertemuskelen pga. vasodilatasjon."}]},{"type":"paragraph","content":[{"type":"text","text":"Antiarytmisk effekt fordi verapamil spesifik'
    't påvirker hjertes ledningssystem: forsinker ledningstid i AV-knuten og setter ned frekvens i sinusknuten."}]},{"type":"paragraph","content":[{"type":"text","text":"Blodtrykksreduksjon ved monoterapi, sittende systolisk/diastolisk blodtrykk: 14,4 ± 2,1 / 12,1 ± 2,8 mmHg (gjennomsnitt ± SD), ifølge metastudien fra Wu et al. (2005)."}]}]},"kort":[{"maal":"Spenningsstyrte L-type Ca2+-kanaler","effekt'
    '":"Hemmer / blokkerer","mekanisme":"kanalblokkering","retning":"ned","merknad":"Gjelder både hjertemuskelceller og glatt muskulatur; gir vasodilatasjon og påvirker AV- og sinusknute","dokument":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Kalsiumantagonist, fenylalkylaminderivat. Hemmer selektivt langsomme spenningstyrte L-type kalsiumkanaler i sarcolemma i både h'
    'jertemuskelceller og glatte muskelceller. Dette fører også til mindre frigivelse av kalsiumioner intracellulært. Effekten er vasodilatasjon (redusert afterload), nedsatt perifer motstand og reduksjon i blodtrykk. Vasodilatasjon skjer også i kransarteriene."}]},{"type":"paragraph","content":[{"type":"text","text":"Redusert smerte ved angina pectoris fordi verapamil reduserer hjertets pumpekraft som'
    ' betyr redusert oksygenbehov og samtidig øker blodforsyningen til hjertemuskelen pga. vasodilatasjon."}]},{"type":"paragraph","content":[{"type":"text","text":"Antiarytmisk effekt fordi verapamil spesifikt påvirker hjertes ledningssystem: forsinker ledningstid i AV-knuten og setter ned frekvens i sinusknuten."}]},{"type":"paragraph","content":[{"type":"text","text":"Blodtrykksreduksjon ved monoter'
    'api, sittende systolisk/diastolisk blodtrykk: 14,4 ± 2,1 / 12,1 ± 2,8 mmHg (gjennomsnitt ± SD), ifølge metastudien fra Wu et al. (2005)."}]}]}}]}]'::jsonb) loop
    select s.objekt_id into side from public.infosider s where s.tilstand = 'publisert' and s.slug = konvertering->>'stoff';

    -- Teksten slik den ble importert, uten upublisert utkast.
    select u.objekt_id, u.revisjon, r.innhold into e
    from public.innholdselementer t
    join public.objekttilstander u on u.objekt_id = t.objekt_id and u.tilstand = 'utkast'
    join public.objekttilstander p on p.objekt_id = t.objekt_id and p.tilstand = 'publisert' and p.revisjon = u.revisjon
    join public.objektrevisjoner r on r.objekt_id = t.objekt_id and r.revisjon = u.revisjon
    where t.tilstand = 'publisert' and t.infoside_id = side
      and t.panel = 'farmakodynamikk' and t.elementtype = 'riktekst'
      and r.innhold->'data'->'dokument' = konvertering->'fra'
    order by t.posisjon, t.objekt_id
    limit 1;
    if not found then
      raise notice 'Gjør ikke om farmakodynamikken på %: fant ikke teksten slik den ble importert, eller den har et upublisert utkast.',
        konvertering->>'stoff';
      continue;
    end if;

    -- Kortene, i rekkefølge, med kildene til teksten.
    perform set_config('far.revisjonskilde', 'Farmakodynamikken strukturert som mekanismekort etter kartleggingen i docs/farmakodynamikk-kort-kartlegging.md', true);
    for kort, posisjon in select k, i - 1 from jsonb_array_elements(konvertering->'kort') with ordinality as a(k, i) loop
      objekt := (public.opprett_utkast('innholdselement', jsonb_build_object(
        'infoside', side,
        'panel', 'farmakodynamikk',
        'posisjon', posisjon,
        'elementtype', 'mekanismekort',
        'data', kort
      ) || jsonb_strip_nulls(jsonb_build_object('referanser', e.innhold->'referanser')))).id;
      perform public.publiser_utkast(objekt, 1);
    end loop;

    -- Teksten tas bort fra siden, men står i historikken.
    perform set_config('far.revisjonskilde', 'Farmakodynamikkteksten erstattet av mekanismekort etter kartleggingen i docs/farmakodynamikk-kort-kartlegging.md', true);
    perform public.lagre_utkast(e.objekt_id, e.revisjon, jsonb_set(e.innhold, '{panel}', to_jsonb('fjernet'::text)));
    perform public.publiser_utkast(e.objekt_id, e.revisjon + 1);
  end loop;
end
$farmakodynamikk$;